theorem actual_source_controllability_columns_are_independent :
    IsUnit (!![sourceB 0,(sourceA *ᵥ sourceB) 0;
      sourceB 1,(sourceA *ᵥ sourceB) 1] : Matrix (Fin 2) (Fin 2) ℝ)

theorem actual_whole_trajectory_margin_set_is_nonempty {X : Type*}
    (F : ClosedLoop X) (margin : X→ℝ) (x : X) :
    (trajectoryMargins F margin x).Nonempty

theorem actual_permanent_exclusion_leaves_no_global_exploration_candidate_but_recheck_releases_the_optimum :
    actualGlobalExplorationEligibility (Set.univ : Set Bool) {false} {true}=∅ ∧
      actualGlobalExplorationEligibility (Set.univ : Set Bool) {false}
        (actualRecheckedExclusion {true} actualExpandedCoverage)={true}

theorem actual_nondegenerate_noise_makes_every_positive_time_violation_probability_positive
    (k goal sigma : ℝ) (T : ℕ) (t : Fin T) (hsigma : sigma ≠ 0) :
    0 < (noiseLaw T).real {w | 1 < stateAt k goal sigma t w}

theorem actual_source_event_is_exactly_the_count_at_least_one_event
    {Ω : Type*} [MeasurableSpace Ω] {T : ℕ} (events : Fin (T+1)→Set Ω) :
    everUnsafe events={ω | (1:ℝ)≤ unsafeCount events ω}

theorem actual_upper_sign_corner_is_in_original_box {ι κ : Type*}
    (W : Matrix κ ι ℝ) (lo hi : ι → ℝ) (h : ∀j,lo j≤hi j) (i : κ) :
    upperCorner W lo hi i∈box lo hi

theorem actual_lower_sign_corner_is_in_original_box {ι κ : Type*}
    (W : Matrix κ ι ℝ) (lo hi : ι → ℝ) (h : ∀j,lo j≤hi j) (i : κ) :
    lowerCorner W lo hi i∈box lo hi

theorem actual_upper_corner_uses_original_box_endpoints {ι κ : Type*}
    (W : Matrix κ ι ℝ) (lo hi : ι → ℝ) (i : κ) :
    ∀j,upperCorner W lo hi i j=lo j ∨ upperCorner W lo hi i j=hi j

theorem actual_lower_corner_uses_original_box_endpoints {ι κ : Type*}
    (W : Matrix κ ι ℝ) (lo hi : ι → ℝ) (i : κ) :
    ∀j,lowerCorner W lo hi i j=lo j ∨ lowerCorner W lo hi i j=hi j

theorem actual_standard_upper_sign_formula_is_feasible {ι κ : Type*}
    (W : Matrix κ ι ℝ) (lo hi : ι → ℝ) (h : ∀j,lo j≤hi j) (i : κ) :
    standardUpperWitness W lo hi i∈box lo hi

theorem actual_standard_lower_sign_formula_is_feasible {ι κ : Type*}
    (W : Matrix κ ι ℝ) (lo hi : ι → ℝ) (h : ∀j,lo j≤hi j) (i : κ) :
    standardLowerWitness W lo hi i∈box lo hi

theorem actual_kernel_is_the_strict_stopping_barrier_sublevel
    (a L : ℝ) (ha : 0 < a) :
    printedKernel a L = {z | wallStoppingBarrier a z < L}

theorem actual_kernel_closure_is_the_nonstrict_stopping_barrier_sublevel
    (a L : ℝ) (ha : 0 < a) :
    closure (printedKernel a L) = {z | wallStoppingBarrier a z ≤ L}
